'postmark_message_streams'          => "Message Streams",
'postmark_api_error'                => 'Postmark API error: %s - %s',
'postmark_message_description'  => "<p>Postmark message streams are like different 'buckets' for your emails. Each bucket holds a specific type of email, so it’s easier to manage and helps ensure that the right emails get to the right people.</p>
<ul>
<li><strong>Transactional Emails</strong>: These are important, one-on-one emails, like order confirmations or password resets. They need to be delivered quickly and reliably, so they go into their own bucket.</li>
<li><strong>Broadcast Emails</strong>: These are emails sent to a large group, like newsletters or special offers. They go into a separate bucket because they are less urgent than transactional emails.</li>
</ul>
<p>By separating your emails into different buckets, Postmark helps make sure your important emails always reach the recipient, while also handling your other messages in the right way. This helps with better email delivery and keeps things organized.</p>",
'postmark_stream_choose'            => "Choose which message streams to use for the email types:",
