'spamprevention_captcha'			=> "CAPTCHA",
'bot_antispam_type'					=> "CAPTCHA Type",
'bot_antispam_type_desc'			=> "Computer programs known as <em>spam bots</em> may attempt to register on your site to post unwanted content. CAPTCHA is a test designed to be simple for humans to answer correctly, but difficult for computer programs. The selected CAPTCHA type will display on the registration form of your site and will need to be completed successfully in order to register an account. A CAPTCHA type must be selected to use the Post Before Registering feature.",
'captcha_type_none'					=> "None",
'captcha_type_invisible'			=> "Invisible reCAPTCHA",
'captcha_type_invisible_desc'		=> "Users do not need to do anything. The system intelligently detects if the user is human in the background. <a href='{external.captcha_recaptcha_invisible}' target='_blank' rel='noopener'>Learn more</a>",
'captcha_type_recaptcha2'			=> "reCAPTCHA V2",
'captcha_type_recaptcha2_desc'		=> "The user clicks a \"I'm not a robot\" checkbox. <a href='{external.captcha_recaptcha2}' target='_blank' rel='noopener'>Learn more</a>",
'captcha_type_keycaptcha'			=> "keyCAPTCHA",
'captcha_type_keycaptcha_desc'		=> "The user must complete simple jigsaw puzzle. <a href='{external.captcha_keycaptcha}' target='_blank' rel='noopener'>Learn more</a>",
'bot_antispam_type_warning'			=> "Disabling CAPTCHA will put your site at a significant risk to spam. Enabling a CAPTCHA type is strongly recommended.",
'captcha_type_turnstile'			=> "Cloudflare Turnstile",
'captcha_type_turnstile_desc'		=> "The user clicks a \"I'm not a robot\" checkbox. <a href='{external.captcha_turnstile}' target='_blank' rel='noopener'>Learn more</a>",
'turnstile_site_key'				=> "Site Key",
'turnstile_secret_key'				=> "Secret Key",
'turnstile_secret_key_cloud_desc'		=> "Cloudflare Turnstile is already configured for Cloud customers. However, you can create <a href='{external.captcha_turnstile_keys}' target='_blank' rel='noopener'>your own Cloudflare account</a> which will allow you to change the security preference settings.",
'turnstile_secret_key_desc'		=> "In order to use Cloudflare Turnstile, you must create <a href='{external.captcha_turnstile_keys}' target='_blank' rel='noopener'>your own Cloudflare account</a> which will allow you to change the security preference settings.",
'recaptcha2_public_key'				=> "reCAPTCHA Site Key",
'recaptcha2_private_key'			=> "reCAPTCHA Secret Key",
'recaptcha2_private_key_desc'		=> "In order to use reCAPTCHA, you must create <a href='{external.captcha_recaptcha2_keys}' target='_blank' rel='noopener'>your own reCAPTCHA account</a> which will allow you to change the security preference settings.",
'keycaptcha_privatekey'				=> "keyCAPTCHA Key",
'keycaptcha_privatekey_desc'		=> "In order to use keyCAPTCHA, you must <a href='{external.captcha_keykeptcha_signup}' target='_blank' rel='noopener'>create an account</a> and provide your key.",
'guest_captcha_search_target'		=> "Guest posts",
'acplogs__spamprev_settings'		=> "Edited spam prevention settings",
'spamservice_inter_header'			=> "Spam Defense",
'spamservice_inter_body'			=> "<p>Spam Defense is a service available to all clients who hold an active Invision Community license at no extra cost.  When enabled, this service allows you to check new account registrations against our proprietary spammer database, helping to prevent spammers from registering on your site.</p><p><a href='%s'>Configure Spam Defense</a>",
'captcha_type_hcaptcha'				=> "hCaptcha",
'captcha_type_hcaptcha_desc'		=> "The user must click a checkbox and may be required to select certain images from a grid. <a href='{external.captcha_hcaptcha}' target='_blank' rel='noopener'>Learn More</a>",
'hcaptcha_sitekey'					=> "hCaptcha Sitekey",
'hcaptcha_secret'					=> "hCaptcha Secret",
'hcaptcha_secret_desc'				=> "In order to use hCaptcha you must <a href='{external.hcaptcha_signup}' target='_blank' rel='noopener'>create an account</a> and provide your key.",
'hcaptcha_privacy'					=> "We use the hCaptcha anti-bot service (hereinafter \"hCaptcha\") on our website. This service is provided by Intuition Machines, Inc., a Delaware US Corporation (\"IMI\"). hCaptcha is used to check whether the data entered on our website (such as on a login page or contact form) has been entered by a human or by an automated program. To do this, hCaptcha analyzes the behavior of the website or mobile app visitor based on various characteristics. This analysis starts automatically as soon as the website or mobile app visitor enters a part of the website or app with hCaptcha enabled. For the analysis, hCaptcha evaluates various information (e.g. IP address, how long the visitor has been on the website or app, or mouse movements made by the user). The data collected during the analysis will be forwarded to IMI. hCaptcha analysis in the \"invisible mode\" may take place completely in the background. Website or app visitors are not advised that such an analysis is taking place if the user is not shown a challenge. Data processing is based on Art. 6(1)(f) of the GDPR (DSGVO): the website or mobile app operator has a legitimate interest in protecting its site from abusive automated crawling and spam. IMI acts as a \"data processor\" acting on behalf of its customers as defined under the GDPR, and a \"service provider\" for the purposes of the California Consumer Privacy Act (CCPA). For more information about hCaptcha and IMI's privacy policy and terms of use, please visit the following links: https://www.hcaptcha.com/privacy and https://www.hcaptcha.com/terms.",

