'iframely_url_whitelist_desc'			=> "<div class='ipsRichText'>In addition to the default content providers, you can check Iframely for embeddable content for any URL whose domain matches one of these patterns. <ul><li>Use <code>*</code> as a wildcard.</li><li>Note that subdomains must be explicitly specified in a pattern to be allowed</li><li>For example, the pattern <code>google.com</code> would not allow https://www.google.com/, but <code>*.google.com</code> or <code>www.google.com</code> would.</li><li><strong>Only allow embeds for websites that you trust, embedding content from untrusted sources could introduce security risks.</strong></li></ul></div>",
'iframely_err_no_api_key'               => 'No API key specified',
'iframely_err_invalid_api_key'          => 'API Key invalid',
'iframely_manage_link'                  => 'The <a target="_blank" href="{internal.admin.app=core&module=applications&controller=enhancements&do=edit&id=core_Iframely}">Iframely Integration <i class="fa-solid fa-external-link"></i></a> can be used to embed content from additional third party sources, including Facebook and Instagram.',


/* !Simplified Mode */
"r__posting_manage_simplified_mode"	=> "Can manage Simplified Editing mode",
'editor_simplified_mode' => 'Editor Permissions',
'editor_simplified_mode_desc' => 'There are three permission levels of the Post Editor: Minimal, Standard, and Advanced. By default, users will use the Minimal Editor for secondary content such as Comments and Posts, and the Standard Editor for main items such as Topics and Blog Entries. Here you can configure which features are available at which levels. To change the levels each group has access to, see the Content tab in the <a href="{internal.app=core&module=members&controller=groups}">Member Group Settings</a> for a group.',
'editor_mode_all'	=> 'Always',
'editor_mode_regular' => 'Standard & Advanced',
"editor_mode_advanced" => "Only Advanced",
"editor_mode_none" => "Never",
"editor_r__external_embed" => "Can Embed External Content",
"editor_r__external_media" => "Can Embed External Media",
"editor_r__external_media__desc" => "This allows the posting of images stored on external sites and playable videos from streaming video services such as Youtube or Vimeo. This permission has no effect on attachments or uploaded images or videos.",
"editor_r__external_image" => "Can Embed External Images",
"editor_r__external_image__desc" => "This allows the posting of images stored on external sites. This permission has no effect on attachments or uploaded images.",
"editor_r__external_video" => "Can Embed External Videos",
"editor_r__external_video__desc" => "This allows the posting of playable videos from streaming video services such as Youtube or Vimeo. This permission has no effect on attachments or uploaded videos.",
"editor_r__internal_embed" => "Can Embed Internal Content",
"editor_r__raw_embed" => "Can Convert Links to iframes",
"editor_r__raw_embed__desc" => "This allows the posting of custom embeds, such as advertment blocks from sites controlled by a <a href='{internal.app=core&module=settings&controller=posting&tab=embedUrlFilters}'>pre-defined whitelist</a>.",
"editor_r__og_embed" => "Can Embed Link Previews",
"editor_r__og_embed__desc" => "This allows the option of converting a pasted URL into an expanded site preview if the site contains <a href='https://ogp.me' target='_blank'>Open Graph</a> meta data.",
"editor_r__float" => "Can apply float to boxes and images",
"editor_r__heading" => "Can use Headings",
