"g_editor_restriction" => "Editor Permission Level",
"g_editor_restriction_desc"	=> "The Editor used by default in the software, such as in Topics, Blogs and various AdminCP areas. By default, this is Advanced for Administrator Groups and Standard otherwise. See the <a href='{internal.app=core&module=settings&controller=posting&tab=simplifiedMode}'>Editor Permissions</a> page for more information.",
"g_editor_comments_restriction" => "Editor Permissions Level for Comments",
"g_editor_comments_restriction_desc" => 'This is the editor used for secondary content, such as Blog Comments or Reviews. By default, this is Advanced for Administrator Groups and Minimal otherwise.',

'links_external'						=> "Force posted links to open in new windows?",
'links_external_desc'					=> "Setting this to Yes will force all posted links, to other websites, to open in a new window.<br>Changing this setting will only affect new content unless you <a data-confirm href='{internal.app=core&module=settings&controller=posting&do=rebuildUrlRels.csrf}'>rebuild existing content</a>.",
'posts_add_nofollow'					=> "Instruct search engines not to follow posted links?",
'posts_add_nofollow_desc'				=> "Will add rel='nofollow' to posted links that link away from your website. This is recommended so search engines are aware that your site is not connected to sites users post links to.<br>Changing this setting will only affect new content unless you <a data-confirm href='{internal.app=core&module=settings&controller=posting&do=rebuildUrlRels.csrf}'>rebuild existing content</a>.",
'posts_add_nofollow_exclude'			=> "Domains to instruct search engines to follow",
'posts_add_nofollow_exclude_desc'		=> "rel='nofollow' will not be added to any links to the domains specified. Add any domains which your site is connected to or has control over, or which you have an advertising agreement with requiring you to allow links to the domain to be followed. Supply only the domain name instead of a full URL, for example 'site.com' rather than 'https://site.com'.<br>Changing this setting will only affect new content unless you <a data-confirm href='{internal.app=core&module=settings&controller=posting&do=rebuildUrlRels.csrf}'>rebuild existing content</a>.",
'acplogs__url_filter_settings'			=> "Link filter settings edited",
'acplogs__posting_general_settings'		=> "General posting settings edited",
'posting_attachments'					=> "Attachments",
'attach_allowed_types'					=> "Allowed File Types",
'attach_allowed_types_all'				=> "All Files",
'attach_allowed_types_media'			=> "Images &amp; Videos Only",
'attach_allowed_types_images'			=> "Images Only",
'attach_allowed_types_none'				=> "None",
'attach_allowed_types_desc'				=> "You can configure which groups can use attachments and their storage limits in the <a href='{internal.app=core&module=members&controller=groups&searchResult=g_attach}'>group settings</a>.",
'attach_allowed_extensions'				=> "Allowed File Extensions",
'attach_allowed_extensions_desc'		=> "If provided, only files which have a name ending in one of the specified extensions will be allowed.",
'attachment_resample_size'				=> "Maximum image dimensions to save",
'attachment_resample_size_desc'			=> "If an image larger than the these dimensions is uploaded, it will be resized to no bigger than the dimensions and the original image will be discarded. Resizing images reduces their quality so it is normally best to leave this unlimited unless your community uses a lot of images and you want to reduce disk space use.",
'attachment_image_size'					=> "Maximum thumbnail resolution",
'attachment_image_size_desc'			=> "If an image larger than the these dimensions is uploaded, a thumbnail will be created with a resolution no bigger than the specified dimensions. This thumbnail is included directly in the content, while the full-sized image is displayed when the user clicks it. Images can be resized to display at a greater size than their thumbnail's resolution, so it is usually best to keep this quite large so images appear attractive unless your community uses a lot of images and you want to reduce bandwidth use. The settings apply to new images only.",
'attachment_image_size__no_thumbnails' 	=> 'Don\'t create image thumbnails',
'thumbnails_rebuilt'					=> "The attachment thumbnails will be rebuilt in the background",
'refurls_rebuilt'					=> "The link data will be rebuilt in the background",
'max_internalembed_width'				=> "Maximum embedded content width",
'max_internalembed_width_desc'			=> "This setting restricts the size of content (such as topics, albums, OG Link Previews, Social Media Embeds and more) from embedded links. The content will never be wider than the content's container or the user's browser can display.",
'max_embeddedmedia_width'				=> "Maximum embedded media width",
'max_embeddedmedia_width_desc'			=> "This setting restricts the size of embedded media, such as Youtube videos and external images. The media will never be wider than the content's container or the user's browser can display.",
