'word_type_acronym_desc'				=> "The text you enter will show when a user hovers on the word. This can be useful for acronyms that users may not understand. For example, you can make it so if a user posts \"ASAP\" it shows \"As Soon As Possible\" when another user hovers on it.",	
'word_type_link'						=> "Link",
