'username_login_enabled'				=> "Display name logins are enabled",
'username_login_enabled_desc'			=> "Allowing users to log in with a display name can represent a security weakness for your community because display names are public information and malicious users may attempt to login to multiple accounts with common passwords until they find an account for which the passwords work. It is recommended that you only allow users to log in with their email address.",
'username_login_enabled_button'			=> "Edit Login Methods",

'dashboard_tasksrun_broken'				=> "Maintenance Tasks Not Running",
'dashboard_tasksrun_broken_desc'		=> "Important routine maintenance tasks do not appear to be running. This will cause cause significant damage to your community if not resolved.",
'dashboard_tasks_cron_broken_desc_1'	=> "Your community is configured to run routine maintenance tasks using a cron, however, it does not appear to be running This will cause significant damage to your community if not resolved. Check the cron is set up properly, or switch to the <strong>Run Automatically with Traffic</strong> option. If you do not know how to set up a cron, contact your hosting provider or system administrator for assistance.",
'dashboard_tasks_cron_broken_desc_2'	=> "A cron should be set on your server to run the following command every minute:",
'dashboard_tasks_web_broken_desc_1'		=> "Your community is configured to run routine maintenance using a web service, however, it does not appear to be working properly. This will cause significant damage to your community if not resolved. Check the service is set up properly, or switch to the <strong>Run Automatically with Traffic</strong> option.",
'dashboard_tasks_web_broken_desc_2'		=> "The web service should make a call to the following URL every minute (or as frequently as possible):",
'dashboard_tasks_not_enough_desc'		=> "Routine maintenance tasks are performed as users access the site but it looks like the traffic to your community is not sufficient to run these tasks on time. This will cause significant damage to your community if not resolved. It is recommended that you set up a cron or a web service so that these tasks can be run even when there isn't any traffic coming to your community.",
'dashboard_tasks_fix_info'				=> "After fixing the issue you may want to <a href='{internal.app=core&module=overview&controller=notifications&do=dismiss&id=}%d' data-action='dismiss'>hide this notification until tomorrow</a> as it will not automatically dismiss until the backlog has cleared.",

'dashboard_cic_email_quota'				=> "Email Quota Over Limit",
