'dashboard_cic_email_quota_subtitle'	=> "Your community has exceeded its email sending quota for this month. Please contact support for further information.",
'dashboard_url_invalid'					=> "Your URL is not valid.",
'dashboard_url_invalid_desc'			=> "The license key in use is not valid for this site. Please <a href='{internal.app=core&module=support&controller=support}'>contact support</a> for further information.",

'facebook_https_warning_title'			=> "Action Required To Keep Facebook Login﻿ Working",
'facebook_https_warning_title2'			=> "Facebook Login﻿ Not Working",
'facebook_https_warning_desc'			=> "Facebook have <a href='{external.facebook_https}' target='_blank' rel='noopener'>recently announced</a> that from <strong>October 6, 2018</strong> all sites using Facebook login must be using HTTPs. In order to continue using Facebook login you must obtain an SSL certificate. Contact your hosting provider for more information or if you already have a certificate, make sure it is <a href='{internal.app=core&module=settings&controller=login&do=httpsCheck}' data-ipsDialog>configured correctly</a>. If you do not do this, Facebook login will stop working on October 6, 2018.",
'facebook_https_warning_desc_cic'		=> "Facebook have <a href='{external.facebook_https}' target='_blank' rel='noopener'>recently announced</a> that from <strong>October 6, 2018</strong> all sites using Facebook login must be using HTTPs. In order to continue using Facebook login you must obtain an SSL certificate. <a href='{external.client_area}' target='_blank' rel='noopener'>Contact us for more information</a>. If you do not do this, Facebook login will stop working on October 6, 2018.",

