/* Onboarding */
'onboard_welcome_message'				=> "<p><strong>Let's walk through some quick setup.</strong> There are some settings that Community Managers typically need to change right away when setting up a new community. We've grouped some commonly adjusted settings here so that you can quickly step through them and get the basics done.</p><p><strong>This step is optional.</strong> All of the settings here are available elsewhere in the Admin Control Panel should you want to change them later instead.</p><p><strong>Have questions?</strong> Click the Support link at the top right of any page in the Admin Control Panel to get help.</p>",
'acplogs__onboard_settings'				=> "Adjusted settings from the onboarding screen",
'onboard_pagetitle'						=> "Welcome to Invision Community",
'onboard_skipquicksetup'				=> "Skip quick setup",
'onboard_startquicksetup'				=> "Start quick setup",
'onboard_pagetitle_basic'				=> "Quick Setup",
'onboard_subtitle'						=> "We're thrilled you've decided to launch your community with us.",
'initial_logo'							=> "Logo Image",
'initial_logo_desc'						=> "The logo uploaded will be used for outgoing emails and for all installed themes.",
'onboard_remind_later'					=> "Remind Me Later",
'onboard_will_remind'					=> "You will be reminded to complete the setup later",
'mailsub__core_onboard_reminder' 		=> "Finish setting up your new community",
'emailtpl_onboard_reminder'				=> "Onboarding community setup",
'emailstats__onboard_reminder'			=> "Onboarding community setup",
'onboard_welcome_message_email'			=> "<p>Welcome to your new Invision Community installation!</p><p>Now, we know that you have a long to-do list before you open your community. That's why we've put all your most-needed settings (community name, logos, etc.) on a single page to help you make a dent in that list.</p><p>Click the link below to get started.</p><p>Drop a line to our technical support team if you need a little more help!</p>",
'onboard_finish_setup'					=> "Finish setting up my community",
'onboard_email_thanks'					=> "Thanks,",
'onboard_email_tic'						=> "Team Invision Community",
'onboard_next_steps_intro'				=> "Your Invision Community is now ready to use and you can soon start directing visitors to your community. But before you do so, there are a few other optional steps you may want to walk through, so we've highlighted those below.",
'onboard_next_steps_intro2'             => "You can also use the search bar found at the top of every page to look for specific settings, and you can use the <a href='{internal.app=core&module=support&controller=support}'>Support tool</a> to reach out for technical support if you need help. Good luck with your new community!",
'onboard_takeme'						=> "Take me there",
'onboard_next_forums_title'             => "Create Forums",
'onboard_next_forums'					=> "Set up your forum structure to enable members to create new discussions in the appropriate place. Invision Community offers regular discussion and Q&amp;A forums.",
'onboard_next_groups'					=> "Set up the user groups you'll need, along with the access levels and account restrictions for each.",
'onboard_next_groups_title'             => "User Groups",
'onboard_next_staff_title'              => "Administrators &amp; Moderators",
'onboard_next_staff'					=> "Set up additional administrators and moderators who will be responsible for managing the community.",
'onboard_takeme_admins'					=> "Manage Administrators",
'onboard_takeme_mods'					=> "Manage Moderators",
'onboard_next_themes_title'             => "Theme",
'onboard_next_themes'					=> "Adjust the built-in theme to match your own branding, or install new pre-made themes.",
'onboard_next_nexus_title'              => "Monetization",
'onboard_next_nexus'					=> "If you plan to sell subscriptions or products, you'll want to set those up so your members can purchase them.",
'onboard_takeme_subs'					=> "Manage Subscriptions",
'onboard_takeme_packages'				=> "Manage Products",
'onboard_tab_identity'					=> "Site Identity",
'onboard_msg_identity'					=> "This section allows you to configure basic details about your site such as the name, address and social networking profiles affiliated with the site.<br><br>If an address is provided it will be appended automatically to your Privacy Policy and all outgoing emails the community sends. This is often required by local laws.",
'onboard_location_identity'				=> "<strong>Site name, address and social profiles:</strong><br>System ( <i class='fa-solid fa-gears'></i> ) &gt; Settings &gt; General Configuration<br><br><strong>Email addresses:</strong><br>System ( <i class='fa-solid fa-gears'></i> ) &gt; Settings &gt; Email Settings",
'onboard_tab_appearance'				=> "Logos & Appearance",
'onboard_msg_appearance'				=> "Customizing the look and feel of your community and uploading your logo is a simple way to make it unique and your own. Each individual theme can use its own logo, which can be changed by editing each theme, while emails use a single logo for all emails sent by the community.",
'onboard_location_appearance'			=> "<strong>Favicon and application icons:</strong><br>Customization ( <i class='fa-solid fa-paintbrush'></i> ) &gt; Appearance &gt; Icons &amp; Logos<br><br><strong>Theme Logos:</strong><br>Customization ( <i class='fa-solid fa-paintbrush'></i> ) &gt; Appearance &gt; Themes<br><br><strong>Email Logo and primary email color:</strong><br>System ( <i class='fa-solid fa-gears'></i> ) &gt; Settings &gt; Email Settings",
'onboard_tab_tasks'						=> "Tasks",
'onboard_msg_tasks'						=> "By default, background tasks run based on traffic to your community, which is generally low at first. You may wish to use a cron job to run your tasks in order to ensure they are executed even if no one is visiting yet..",
'onboard_location_tasks'				=> "System ( <i class='fa-solid fa-gears'></i> ) &gt; Settings &gt; Advanced Configuration",
'onboard_tab_furls'						=> "Friendly URLs",
'onboard_msg_furls'						=> "Most communities will benefit from using friendly URLs, however you will need to adjust your server configuration before you can do so.",
'onboard_location_furls'				=> "System ( <i class='fa-solid fa-gears'></i> ) &gt; Site Promotion &gt; Search Engine Optimization",
'onboard_tab_privacyterms'				=> "Terms & Privacy Policy",
'onboard_msg_privacyterms'				=> "Let visitors and new members know about your site guidelines, privacy policy and terms and conditions.",
'onboard_location_privacyterms'			=> "System ( <i class='fa-solid fa-gears'></i> ) &gt; Settings &gt; Terms &amp; Privacy Policy",
'onboard_what_are_these'				=> "What are these settings?",
'onboard_where_are_these'				=> "Where can I find these settings later?",
'onboard_skip_step'                     => "Skip this step",
'onboard_complete'                      => "Invision Community Is Ready!",
'onboard_next_steps_subtitle'           => "Now check out this list of next-steps...",
'onboard_tab_spamprevention'			=> "Spam Prevention",
'onboard_msg_spamprevention'			=> "CAPTCHA is a test designed to be simple for humans to answer correctly, but difficult for computer programs. CAPTCHAS are required in many areas where guests can interact with the community.",
'onboard_location_spamprevention'		=> "Members ( <i class='fa-solid fa-user'></i> ) &gt; Content Moderation &gt; Spam Prevention",


