/* ! Security */
'xforward_matching'				=> "Trust IP addresses provided by proxies?",
'xforward_matching_desc'		=> "If your network environment means requests are handled through a proxy (such as in an intranet situation in an office or university, or on a load-balanced server cluster), you may need to enable this setting so that the correct IP address is used. However, when enabled, a malicious user can abuse the system to provide a fake IP address. In most environments, this setting should be left off.",
'match_ipaddress'				=> "Check IP address when validating session?",
'match_ipaddress_desc'			=> "If your site is likely to be used by many users in an intranet situation (such as an office or university), you may need to disable this setting to prevent users being logged out. However, when disabled, there is a greater risk of session hijacking. In most environments, this setting should be left on.",
'disable_functions_title'		=> "Dangerous PHP Functions Enabled",
'disable_functions_desc'		=> "Some functions are enabled on your server which have the potential to cause serious damage to your community or server.",
'disable_functions_desc_1'		=> "Some functions are enabled on your server which have the potential to cause serious damage to your community or server. If you are in a shared hosting environment, some of these functions may bypass the restrictions which prevent one account on the server affecting another. Their presence also increases the amount of damage that could be caused if your AdminCP is compromised.",
'disable_functions_desc_2'		=> "Since Invision Community, and most other web applications do not use these functions, we recommend disabling them on your server, at least within the directory that your community is installed in. You should contact your hosting provider or system administrator and ask them to be added to the <code>disable_functions</code> PHP setting.",
'display_errors_title'			=> "Public Display of PHP Errors Enabled",
'display_errors_desc'			=> "Your server is set to display PHP errors. This is not recommended for production environments as it may cause sensitive information to be publicly disclosed. You should contact your hosting provider or system administrator and ask them to set the <code>display_errors</code> PHP setting to <code>Off</code>.",
'display_errors_subtitle'		=> "Your server is set to display PHP errors. This is not recommended for production environments as it may cause sensitive information to be publicly disclosed.",
'system_check_title'	 		=> "Server Requirements",
'system_check_recommended_blurb' => "Your server does not meet our recommendations. This may prevent you from upgrading to future versions of Invision Community.",
'system_check_recommended_footer' => "You should contact your hosting provider or system administrator and ask them to resolve these issues.",
'system_check_recommended_email' => "Log into your AdminCP to view more information about the recommendations.",
'acplogs__security_settings' 	=> "Updated security settings",
'acplogs__security_conf'		=> "Made configuration file (conf_global.php) read-only",
'security_header_ips'			=> "Security",
'security_header_accounts'		=> "Account Security",
'device_management'				=> "Allow users to see and manage authorized devices?",
