'use_gtm_for_installation' => 'Note that to use Google Tag Manager, you must use the installation snippets provided by Google. If you are already implementing GTM, then you don\'t need anything else here. Otherwise, you can paste the installation snippet in the <a style="text-decoration: none;" href="{internal.app=core&module=applications&controller=enhancements&do=edit&id=core_GoogleTagManager}" target="_blank">Google Tag Manager Integration <i class="fa-solid fa-arrow-up-right-from-square"></i></a> settings page. If you are using Google Analytics or another gtag.js integration, see <a style="text-decoration: none;" href="https://support.google.com/tagmanager/answer/7582054?hl=en&ref_topic=3441530" target="_blank">Google\'s Tag Manager and gtag.js <i class="fa-solid fa-arrow-up-right-from-square"></i></a> guide on the matter for further instruction.',
