'datalayer_handler_event_handler'           => 'Data Layer Event Handler (JavaScript)',
'datalayer_handler_event_handler_desc'      => 'This JavaScript is run whenever a valid DataLayer event occurs. The JavaScript variable, <span class="i-font-family_monospace">_event</span> will contain two properties, <span class="i-font-family_monospace">_key</span> and <span class="i-font-family_monospace">_properties</span>, which come from the Data Layer Events and Properties respectively. Everything in <span class="i-font-family_monospace">_properties</span> is an enabled and PII permitted property, and the handlers are only passed enabled Data Layer events.',
'datalayer_handler_properties_handler'      => 'Data Layer Properties Handler (JavaScript)',
