'cookies_message' => "We have placed <a href='%s'>cookies</a> on your device to help make this website better. You can <a href='%s'>adjust your cookie settings</a>, otherwise we'll assume you're okay to continue.",
'cookies_about' => "Cookies",
'cookie_3rdpartynotice' => "Third Party Cookie Details",
'cookie_3rdpartynotice_desc' => "If your community stores cookies from third parties (such as Google, YouTube, etc) then you can list them here and they will show on the cookie advice page.",
'terms_cookies' => "Cookies",
'loc_viewing_cookie_policy' => "Viewing the cookie policy page",
'loc_viewing_cookie_policy_action' => "%s is reading the cookie policy page",
'cookies_about_header' => "Cookies are small text files that are placed on your computer by websites that you visit. They are widely used in order to make websites work, or work more efficiently, as well as to provide information to the owners of the site. Depending on your access level and actions on the site, various preference based cookies may be set to enrich your experience. These cookies are used to remember your theme, language and item marking preferences, etc.",
'cookies_change_header' => "How do I change my cookie settings?",
'cookies_change_text' => "Most web browsers allow some control of most cookies through the browser settings. To find out more about cookies, including how to see what cookies have been set and how to manage and delete them, visit <a href='https://www.aboutcookies.org' rel='noopener nofollow' target='_blank'>www.aboutcookies.org</a> or <a href='https://www.allaboutcookies.org' rel='nofollow noopener' target='_blank'>www.allaboutcookies.org</a>.<br>To opt out of being tracked by Google Analytics across all websites visit <a href='https://tools.google.com/dlpage/gaoptout' rel='nofollow noopener' target='_blank'>https://tools.google.com/dlpage/gaoptout</a>.",
'cookie_session_front' => "This cookie contains the ID of your current session.",
'cookie_member_id' => "Your member ID. Used to identify if you are logged in.",
'cookie_loggedIn' => "This cookie is set after login, it is used by caching mechanisms to identify if you are logged in.",
'cookie_login_key' => "A unique key to authenticate your member ID cookie. This cookie is set after you log in when you tick 'Remember Me' so you can be automatically logged in again in the future.",
'cookie_device_key' => "This cookie is set after you log in when you tick 'Remember Me' so you can be automatically logged in again in the future. It is also used to improve account security.",
'cookies_third_party' => "Third Party Cookies",
'cookies_third_party_desc' => "The site owner may set additional cookies in addition to the standard cookies above. These cookies are often used for website usage tracking, or set by embedded service providers when viewing embedded content from providers such as YouTube and Vimeo, etc.",
'cookies_standard' => "Essential Cookies",
'cookieconstent_reject'				=> "Reject",
